import { getTasks, createTask, createLabel, addLabelToTask } from "wasp/client/operations";

type Label = { id: number; name: string };
type Task = { id: number; description: string; labels: Label[] };

export function MainPage() {
  const { data: tasks, isLoading, error } = useQuery(getTasks);

  const createTaskFn = useAction(createTask);
  const createLabelFn = useAction(createLabel);
  const addLabelToTaskFn = useAction(addLabelToTask);

  const [taskDescription, setTaskDescription] = useState("");
  const [labelName, setLabelName] = useState("");

  // Per-task selected label state: { [taskId]: labelId }
  const [selectedLabels, setSelectedLabels] = useState<Record<number, number>>({});

  // Collect all unique labels from all tasks
  const allLabels: Label[] = [];
  const seenIds = new Set<number>();
  if (tasks) {
    for (const task of tasks as Task[]) {
      for (const label of task.labels) {
        if (!seenIds.has(label.id)) {
          seenIds.add(label.id);
          allLabels.push(label);
        }
      }
    }
  }

  async function handleCreateTask(e: React.FormEvent) {
    e.preventDefault();
    if (!taskDescription.trim()) return;
    await createTaskFn({ description: taskDescription.trim() });
    setTaskDescription("");
  }

  async function handleCreateLabel(e: React.FormEvent) {
    e.preventDefault();
    if (!labelName.trim()) return;
    await createLabelFn({ name: labelName.trim() });
    setLabelName("");
  }

  async function handleAddLabel(taskId: number) {
    const labelId = selectedLabels[taskId];
    if (!labelId) return;
    await addLabelToTaskFn({ taskId, labelId });
    setSelectedLabels((prev) => ({ ...prev, [taskId]: 0 }));
  }

  return (
    <div style={{ maxWidth: 700, margin: "40px auto", fontFamily: "sans-serif", padding: "0 16px" }}>
      <h1 style={{ fontSize: 28, marginBottom: 8 }}>Tasks & Labels</h1>
      <p style={{ color: "#666", marginBottom: 32 }}>
        Manage tasks and their associated labels (many-to-many).
      </p>

      {/* Create Task Form */}
      <section style={{ marginBottom: 32 }}>
        <h2 style={{ fontSize: 18, marginBottom: 8 }}>Create Task</h2>
        <form onSubmit={handleCreateTask} style={{ display: "flex", gap: 8 }}>
          <input
            type="text"
            placeholder="Task description"
            value={taskDescription}
            onChange={(e) => setTaskDescription(e.target.value)}
            style={{ flex: 1, padding: "8px 12px", borderRadius: 6, border: "1px solid #ccc", fontSize: 14 }}
          />
          <button
            type="submit"
            style={{ padding: "8px 18px", borderRadius: 6, background: "#4f46e5", color: "#fff", border: "none", cursor: "pointer", fontSize: 14 }}
          >
            Add Task
          </button>
        </form>
      </section>

